"use client";
/* Moss, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Moss(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("moss"); }, []);
  return React.createElement("piix-pal", { "pal": "moss", ...piixAttrs(props) });
}

export default Moss;
